package repository;
import java.lang.reflect.*;import java.util.*;import model.annotation.Id;
public class Repository<T> {private final HashMap<String,T> items=new HashMap<>();public T save(T entity){String id=readId(entity);items.put(id,entity);return entity;}@SafeVarargs public final void saveAll(T... entities){for(T e:entities)save(e);}public T findById(String id){return items.get(id);}public ArrayList<T> findAll(){return new ArrayList<>(items.values());}public boolean delete(String id){return items.remove(id)!=null;}private String readId(T entity){for(Class<?> c=entity.getClass();c!=null;c=c.getSuperclass())for(Field f:c.getDeclaredFields())if(f.isAnnotationPresent(Id.class))try{f.setAccessible(true);return String.valueOf(f.get(entity));}catch(IllegalAccessException e){throw new IllegalStateException(e);}throw new IllegalArgumentException("No @Id field on "+entity.getClass().getSimpleName());}}
